files.content:
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1c2c;
  font-family: 'Courier New', Courier, monospace;
  font-size: 18px;
  color: #f4f4f4;
  padding: 16px;
}
.card {
  background: #29366f;
  border: 4px solid #f4f4f4;
  box-shadow: 8px 8px 0 #5d275d;
  padding: 24px;
  width: 100%;
  max-width: 520px;
  image-rendering: pixelated;
}
.pixel-title {
  margin: 0 0 20px;
  font-size: 1.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  text-align: center;
  color: #ffcd75;
  text-shadow: 2px 2px 0 #5d275d;
}
.input-row {
  display: flex;
  gap: 10px;
  margin-bottom: 16px;
}
#todo-input {
  flex: 1;
  padding: 12px;
  font: inherit;
  color: #1a1c2c;
  background: #f4f4f4;
  border: 4px solid #1a1c2c;
  outline: none;
}
#todo-input:focus {
  border-color: #ffcd75;
  box-shadow: 0 0 0 2px #ffcd75;
}
.pixel-btn {
  font: inherit;
  font-weight: bold;
  padding: 12px 18px;
  color: #1a1c2c;
  background: #ffcd75;
  border: 4px solid #1a1c2c;
  cursor: pointer;
  transition: transform 0.05s, background 0.1s;
}
.pixel-btn:hover { background: #ffe9a8; }
.pixel-btn:focus-visible {
  outline: 3px solid #f4f4f4;
  outline-offset: 2px;
}
.pixel-btn:active {
  transform: translate(2px, 2px);
  background: #e0b050;
}
.counts {
  margin: 0 0 12px;
  font-size: 1rem;
  color: #f4f4f4;
  text-align: center;
}
.counts span {
  font-weight: bold;
  color: #ffcd75;
}
.task-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.task-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #1a1c2c;
  border: 3px solid #5d275d;
  padding: 8px 10px;
}
.task-list li input[type="checkbox"] {
  width: 22px;
  height: 22px;
  accent-color: #ffcd75;
  cursor: pointer;
  flex-shrink: 0;
}
.task-list li .todo-text {
  flex: 1;
  word-break: break-word;
  color: #f4f4f4;
}
.task-list li .todo-text.done {
  text-decoration: line-through;
  color: #a0a0a0;
}
.delete-btn {
  font: inherit;
  font-size: 0.9rem;
  padding: 6px 10px;
  color: #f4f4f4;
  background: #5d275d;
  border: 2px solid #f4f4f4;
  cursor: pointer;
  flex-shrink: 0;
}
.delete-btn:hover { background: #7a3a7a; }
.delete-btn:focus-visible {
  outline: 3px solid #ffcd75;
  outline-offset: 2px;
}
.delete-btn:active { transform: translate(1px, 1px); }
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
[hidden] { display: none !important; }
@media (max-width: 400px) {
  .card { padding: 16px; }
  .pixel-title { font-size: 1.4rem; }
  .input-row { flex-direction: column; }
  .pixel-btn { width: 100%; }
}

(function () {
  'use strict';

  const input = document.getElementById('todo-input');
  const addBtn = document.getElementById('todo-add');
  const totalEl = document.getElementById('todo-total');
  const remainingEl = document.getElementById('remaining');
  const list = document.getElementById('todo-list');

  let nextId = 1;
  const tasks = [];

  function updateCounts() {
    totalEl.textContent = String(tasks.length);
    const remaining = tasks.filter(t => !t.done).length;
    remainingEl.textContent = String(remaining);
  }

  function createTaskElement(task) {
    const li = document.createElement('li');
    li.dataset.id = String(task.id);

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = 'todo-check-' + task.id;
    checkbox.checked = task.done;
    checkbox.setAttribute('aria-label', 'Mark task ' + task.id + ' as done');
    checkbox.addEventListener('change', function () {
      task.done = checkbox.checked;
      textSpan.classList.toggle('done', task.done);
      updateCounts();
    });

    const textSpan = document.createElement('span');
    textSpan.className = 'todo-text';
    textSpan.id = 'todo-text-' + task.id;
    textSpan.textContent = task.text;
    if (task.done) textSpan.classList.add('done');

    const delBtn = document.createElement('button');
    delBtn.type = 'button';
    delBtn.className = 'delete-btn';
    delBtn.id = 'todo-delete-' + task.id;
    delBtn.textContent = 'Delete';
    delBtn.setAttribute('aria-label', 'Delete task ' + task.id);
    delBtn.addEventListener('click', function () {
      const idx = tasks.indexOf(task);
      if (idx !== -1) tasks.splice(idx, 1);
      li.remove();
      updateCounts();
    });

    li.appendChild(checkbox);
    li.appendChild(textSpan);
    li.appendChild(delBtn);
    return li;
  }

  function addTask() {
    const text = input.value.trim();
    if (!text) return;
    const task = { id: nextId++, text: text, done: false };
    tasks.push(task);
    list.appendChild(createTaskElement(task));
    input.value = '';
    input.focus();
    updateCounts();
  }

  addBtn.addEventListener('click', addTask);
  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      e.preventDefault();
      addTask();
    }
  });

  updateCounts();
})();
